// ============================================================
//  ⚙️  KONFIGURATION — hier anpassen
// ============================================================
const KONFIG = {
  // Interne Adresse der Bridge (gleiches Docker-Netz wie n8n):
  bridgeUrl: 'http://claude-bridge:8790',

  // Öffentliche URL, unter der Workflow 2 den Callback entgegennimmt.
  // Muss von der Bridge aus erreichbar sein (im Docker-Netz reicht der
  // Container-Name):
  callbackUrl: 'http://n8n:5678/webhook/claude-callback',

  // Spracherkennung. Für lokal (Container "speaches"/faster-whisper):
  //   sttUrl: 'http://speaches:8000/v1/audio/transcriptions'
  //   sttModell: 'Systran/faster-whisper-large-v3'
  // und im Node "Transkribieren" die Authentifizierung auf "None" stellen.
  sttModell: 'gpt-4o-transcribe',
  sprache: 'de',

  // Kanal -> Projekt. Leer lassen: die Bridge erkennt das Projekt am Diktat.
  // Beispiel: { 'C01ABCDEFG': 'kierp' }
  kanalProjekte: {},

  // Nur diese Slack-Nutzer dürfen den Agenten steuern (leer = jeder im
  // Workspace, der den Bot erreichen kann). Empfehlung: eigene ID eintragen.
  erlaubteNutzer: [],

  // Nur Ereignisse aus diesem Workspace annehmen (leer = egal):
  erlaubteTeams: [],
};
// ============================================================

const eingang = $input.first();
const kopf = eingang.json.headers || {};

if (!eingang.binary || !eingang.binary.data) {
  throw new Error('Kein Rohkörper. Im Webhook-Node die Option "Raw Body" aktivieren.');
}
const roh = Buffer.from(eingang.binary.data.data, 'base64').toString('utf8');

// --- Slack-Signatur prüfen -------------------------------------------------
async function hmacHex(secret, daten) {
  try {
    return require('crypto').createHmac('sha256', secret).update(daten).digest('hex');
  } catch (e) {
    // Sandbox erlaubt kein require -> WebCrypto versuchen
  }
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = await crypto.subtle.sign('HMAC', key, enc.encode(daten));
  return Array.from(new Uint8Array(mac)).map(b => b.toString(16).padStart(2, '0')).join('');
}

const secret = $env.SLACK_SIGNING_SECRET || '';
const zeitstempel = kopf['x-slack-request-timestamp'];
const signatur = kopf['x-slack-signature'];
let signaturGeprueft = false;

if (secret && zeitstempel && signatur) {
  if (Math.abs(Date.now() / 1000 - Number(zeitstempel)) > 300) {
    throw new Error('Slack-Anfrage ist älter als 5 Minuten — abgewiesen (Replay-Schutz).');
  }
  let hex = null;
  try {
    hex = await hmacHex(secret, `v0:${zeitstempel}:${roh}`);
  } catch (e) {
    // Weder require('crypto') noch WebCrypto verfügbar: siehe docs/SICHERHEIT.md
  }
  if (hex !== null) {
    if (`v0=${hex}` !== signatur) throw new Error('Slack-Signatur ungültig — abgewiesen.');
    signaturGeprueft = true;
  }
}

const koerper = JSON.parse(roh);

// --- Handshake beim Einrichten der Slack-App -------------------------------
if (koerper.type === 'url_verification') {
  return [{ json: { aktion: 'challenge', challenge: koerper.challenge, konfig: KONFIG } }];
}

const abbrechen = (grund) => [{ json: { aktion: 'ignorieren', grund, konfig: KONFIG } }];

// Slack wiederholt bei Timeout — Wiederholungen niemals erneut ausführen.
if (kopf['x-slack-retry-num']) return abbrechen('Slack-Wiederholung');

if (KONFIG.erlaubteTeams.length && !KONFIG.erlaubteTeams.includes(koerper.team_id)) {
  return abbrechen('fremder Workspace');
}

const e = koerper.event || {};
if (e.bot_id || e.subtype === 'bot_message' || e.user === koerper.authorizations?.[0]?.user_id) {
  return abbrechen('eigene Nachricht');
}

const istDirektnachricht = e.type === 'message' && e.channel_type === 'im';
const istErwaehnung = e.type === 'app_mention';
if (!istDirektnachricht && !istErwaehnung) return abbrechen(`Ereignistyp ${e.type}`);

if (KONFIG.erlaubteNutzer.length && !KONFIG.erlaubteNutzer.includes(e.user)) {
  return abbrechen(`Nutzer ${e.user} nicht freigegeben`);
}

// Erwähnung "<@U123> mach xy" -> "mach xy"
const text = (e.text || '').replace(/<@[A-Z0-9]+>/g, '').trim();
const audio = (e.files || []).find(f => (f.mimetype || '').startsWith('audio/'));

if (!audio && !text) return abbrechen('weder Text noch Sprachdatei');

return [{
  json: {
    aktion: 'verarbeiten',
    konfig: KONFIG,
    signaturGeprueft,
    kanal: e.channel,
    nutzer: e.user,
    threadTs: e.thread_ts || e.ts,
    text,
    hatAudio: Boolean(audio),
    datei: audio
      ? { id: audio.id, url: audio.url_private_download || audio.url_private, name: audio.name }
      : null,
  },
}];

// Antwort der Spracherkennung (OpenAI-kompatibel: { text: "..." })
const antwort = $input.first().json;
const transkript = (antwort.text || antwort.transcript || '').trim();
if (!transkript) throw new Error('Die Spracherkennung hat keinen Text geliefert.');
return [{ json: { transkript, quelle: 'sprache' } }];

// Getippte Nachricht — kein Umweg über die Spracherkennung.
const start = $('Slack prüfen').first().json;
return [{ json: { transkript: (start.text || '').trim(), quelle: 'text' } }];

const start = $('Slack prüfen').first().json;
const KONFIG = start.konfig;
const transkript = ($input.first().json.transkript || '').trim();
if (!transkript) throw new Error('Leerer Auftrag.');

const klein = transkript.toLowerCase();

// Gesprochene Steuerworte
const neuStarten = /(neu anfangen|von vorne|vergiss (das|alles)|neues thema|neue aufgabe)/.test(klein);
const nurPlanen  = /(nur planen|erst(mal)? planen|mach (mir )?(erst )?einen plan|nichts ändern)/.test(klein);

return [{
  json: {
    prompt: transkript,
    // null = die Bridge sucht das Projekt selbst aus dem Diktat
    projekt: KONFIG.kanalProjekte[start.kanal] || null,
    permission_mode: nurPlanen ? 'plan' : null,
    conversation_key: `slack:${start.kanal}:${start.threadTs}`,
    neu_starten: neuStarten,
    callback_url: KONFIG.callbackUrl,
    meta: {
      kanal: start.kanal,
      thread_ts: start.threadTs,
      nutzer: start.nutzer,
      quelle: $input.first().json.quelle,
    },
    vorschau: transkript.length > 500 ? transkript.slice(0, 500) + ' …' : transkript,
  },
}];
